{
  "description": "The creature is shown in right-facing lateral view with a low, elongated body supported by four short limbs. The head is broad, flattened and pale pink with smooth, slightly glossy skin, a blunt snout, small nostrils at the tip, and large round dark eyes on the sides. Immediately behind the head on each side of the neck are three feathery, pinkish-red external gills with fine filamentous branches. The entire dorsal surface from the neck to the base of the tail is covered by a continuous armor of overlapping large rounded brown scales with darker centers and lighter edges. The ventral, lateral, and limb skin is pale pink, hairless and deeply wrinkled with transverse folds along the flanks and limbs. The limbs are thick and end in broad five-toed feet with small claws. A thick, wrinkled pale pink tail extends posteriorly from the body, partially cropped by the left edge of the image and partially covered dorsally by the scaly armor.",
  "parts": [
    {
      "part": "head",
      "looks_like": "broad, flattened and blunt-snouted, pale pink with smooth slightly glossy skin, large round glossy black eyes with a pale bluish ring on the sides and small nostrils at the tip",
      "where": "at the anterior end of the body, in front of the gills and dorsal scaly covering"
    },
    {
      "part": "gills",
      "looks_like": "six feathery external gills, pinkish-red with a central stalk and many fine filamentous branches, three plumes on each side",
      "where": "arising from the neck immediately behind the head, three on the left side and three on the right side"
    },
    {
      "part": "legs",
      "looks_like": "four short, thick, pale pink limbs with deeply wrinkled skin and transverse folds, muscular and columnar",
      "where": "ventrolaterally under the body, two forelimbs under the chest and two hindlimbs under the mid-body"
    },
    {
      "part": "feet",
      "looks_like": "broad fleshy feet with five short toes each, tipped with small pale brown claws",
      "where": "at the distal ends of all four legs, in contact with the ground"
    },
    {
      "part": "tail",
      "looks_like": "thick, pale pink, heavily wrinkled and fleshy, tapering slightly, partially covered dorsally by scales",
      "where": "extending posteriorly from the rear of the body, partially visible and cropped by the left edge of the image"
    },
    {
      "part": "plates",
      "looks_like": "overlapping large rounded keratinous plates, dark brown with lighter brown edges and a glossy surface, arranged in diagonal rows",
      "where": "forming a continuous dorsal armor covering the back from behind the gills to the tail base, ending abruptly above the wrinkled ventral skin"
    },
    {
      "part": "scales",
      "looks_like": "same overlapping large rounded brown scales as the plates, with concentric growth lines and darker centers",
      "where": "covering the entire dorsal and dorsolateral surface of the body and tail base"
    },
    {
      "part": "markings",
      "looks_like": "no distinct spots, stripes or color patches; contrast between the dark brown scaly dorsum and the uniform pale pink wrinkled skin with horizontal creases on the flanks, belly and limbs",
      "where": "over the whole body, with the wrinkled pale skin on the head, sides, belly and limbs and the brown scales on the back"
    }
  ],
  "attached_objects": [],
  "animals": [
    "axolotl",
    "pangolin"
  ],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
